const TENS=['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
function houseNumber(value){let n=Math.floor(Number(value));if(!Number.isSafeInteger(n)||n<0)return String(value).split('').map(c=>SMALL[Number(c)]||'').join(' ');if(n<20)return SMALL[n];if(n<100)return TENS[Math.floor(n/10)]+(n%10?' '+SMALL[n%10]:'');if(n<1000)return houseNumber(Math.floor(n/100))+' hundred'+(n%100?' '+houseNumber(n%100):'');for(const [scale,name]of [[1e12,'trillion'],[1e9,'billion'],[1e6,'million'],[1000,'thousand']])if(n>=scale)return houseNumber(Math.floor(n/scale))+' '+name+(n%scale?' '+houseNumber(n%scale):'')}
function normalizeHouseText(text){return String(text).replace(/’/g,"'").replace(/\bPTS\b/gi,'points').replace(/\bRNG\b/g,'random number generator').replace(/\bV\.0(\d)\b/g,'version $1').replace(/(\d)[,](?=\d{3}(?:\D|$))/g,'$1').replace(/(\d)[–—-](?=\d)/g,'$1 to ').replace(/(^|\s)-(?=\d)/g,'$1minus ').replace(/\d+(?:\.\d+)?/g,n=>{const p=n.split('.');return houseNumber(p[0])+(p[1]?' point '+p[1].split('').map(d=>SMALL[+d]).join(' '):'')}).replace(/%/g,' percent ').replace(/[×]/g,' times ').replace(/[→]/g,' to ').replace(/[—–;:]/g,', ').replace(/[“”]/g,'').replace(/[^a-zA-Z'.,!?…\s]/g,' ').replace(/\s+/g,' ').trim()}
function textToPhonemeIds(input){const text=normalizeHouseText(input);const phones=['_'],tones=[0];for(const token of text.match(/[a-zA-Z]+(?:'[a-zA-Z]+)?|[.,!?…]/g)||[]){if(/[.,!?…]/.test(token)){phones.push(token);tones.push(0);continue}const key=token.toUpperCase(),arpa=CMU[key]||key.split('').flatMap(c=>CMU[c]||[]);for(const p of arpa){const m=p.match(/\d$/);const raw=(m?p.slice(0,-1):p).toLowerCase();phones.push(raw==='v'?'V':raw);tones.push(m?Number(m[0])+1:0)}}phones.push('_');tones.push(0);const phoneIds=[],toneIds=[],langIds=[];for(let i=0;i<phones.length;i++){phoneIds.push(0,SYM[phones[i]]??SYM.UNK);toneIds.push(0,tones[i]+TONE_OFFSET);langIds.push(0,LANG_ID)}phoneIds.push(0);toneIds.push(0);langIds.push(0);return{phoneIds,toneIds,langIds}}

/* Pronunciations for the four vault confrontations. */
Object.assign(CMU,{PERHAPS:["P","ER0","HH","AE1","P","S"],ARRANGEMENT:["AH0","R","EY1","N","JH","M","AH0","N","T"],TAUGHT:["T","AO1","T"],TESTS:["T","EH1","S","T","S"],DOORS:["D","AO1","R","Z"],SURRENDER:["S","ER0","EH1","N","D","ER0"]});
